import{_ as t,b as i,c as a,g as n}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/20.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/20.md"}'),o={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/20.md"};function d(_,e,r,p,l,P){return i(),a("div",null,[...e[0]||(e[0]=[n('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 20 章&lt;概率模型学习&gt;，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来</p><h2 id="一个二值变量x-观测到10次数据-7次true-3次false。" tabindex="-1">一个二值变量X，观测到10次数据：7次True，3次False。</h2><p>(1) 使用最大似然估计求 P(X=&quot;True&quot;)。 (2) 假设先验为Beta分布 Beta(α=2,β=2)，求最大后验估计（MAP）的P(X=True)。 (3) 解释为什么MAP估计在数据量小时比MLE更稳健。</p><h2 id="给定一个简单的贝叶斯网络-a→b-只有两个二值变量。完整数据如下" tabindex="-1">给定一个简单的贝叶斯网络 A→B，只有两个二值变量。完整数据如下：</h2><p>(A,B)：(0,0) 3次，(0,1) 1次，(1,0) 2次，(1,1) 4次。 (1) 用MLE计算CPT参数 P(A=1),P(B=1∣A=0),P(B=1∣A=1)。 (2) 如果添加Dirichlet先验（等效样本数 α=1 对每个条件概率表），求MAP估计的相应概率。</p><h2 id="解释期望最大化-em-算法的核心思想-以及它的两个步骤-e步和m步-分别做什么。为什么em算法能保证收敛" tabindex="-1">解释期望最大化（EM）算法的核心思想，以及它的两个步骤（E步和M步）分别做什么。为什么EM算法能保证收敛？</h2><h2 id="高斯混合模型-gmm-的em手动模拟" tabindex="-1">高斯混合模型（GMM）的EM手动模拟：</h2><p>假设一维数据点：x=[1,2,5,6]，来源于两个高斯分布（分量1和2）。初始参数： μ_1=1.5,σ_1^2=1,μ_2=5.5,σ_2^2=1，混合系数 π_1=π_2=0.5。 (1) 执行一次EM迭代的E步：计算每个数据点属于分量1的后验概率 P(z_i=1∣x_i)（公式用高斯PDF）。 (2) 执行M步：更新 μ_1,μ_2,π_1（只更新均值即可，方差固定）。写出新的均值。 (3) 观察均值的变化方向，说明是否合理。</p><h2 id="贝叶斯网络结构学习评分" tabindex="-1">贝叶斯网络结构学习评分：</h2><p>对于网络结构 G，BIC评分为 BIC=ln⁡P(D∣G,θ ̂)-d/2 ln⁡N，其中 d 是参数个数，N 是样本数。现有两个候选结构： 结构1：A→B（边一个），参数个数 d_1=3（P(A), P(B|A)两个条件概率表，自由度：P(A)1个，P(B|A)2个，共3）。 结构2：A 和 B 独立（无边），参数个数 d_2=2（P(A)和P(B)各1个自由度）。 给定样本数 N=100，最大对数似然值：ln⁡L_1=-200，ln⁡L_2=-205。计算两个结构的BIC，并判断哪个更好。</p><h2 id="em算法用于缺失数据" tabindex="-1">EM算法用于缺失数据：</h2><p>一个二值变量 X 和 Y，部分数据缺失。完整观测有：(0,0) 10次，(0,1) 5次，(1,0) 8次，(1,1) 7次。另外有20个样本只观测到了 X 的值（其中 X=0 有12个，X=1 有8个），而 Y 缺失。假设初始参数：P(X=1)=0.5，P(Y=1∣X=0)=0.3，P(Y=1∣X=1)=0.7。执行一次EM迭代的E步：计算每个缺失样本的 P(Y∣X) 后验分布，然后M步：用填充后的期望计数更新参数。写出更新后的 P(X=1) 和 P(Y=1∣X=0)。</p><h2 id="隐变量模型与em" tabindex="-1">隐变量模型与EM：</h2><p>在一个学生考试成绩分析中，观测到两个考试分数（S_1,S_2），假设存在一个隐变量“能力” Z∈{&quot;低&quot;,&quot;中&quot;,&quot;高&quot;}，且给定能力下两科成绩独立服从高斯分布。 (1) 写出完整的概率模型（包括先验 P(Z)，条件高斯 P(S_1∣Z), P(S_2∣Z)）。 (2) 你收集了1000名学生的分数（连续值），但不知道能力。详细描述如何使用EM算法估计模型参数（均值、方差、混合系数）。 (3) 如果忽略隐变量，直接对两科成绩拟合二元高斯分布，会有什么问题？</p><h2 id="结构学习与因果发现" tabindex="-1">结构学习与因果发现：</h2><p>你有一个包含四个变量（A,B,C,D）的数据集，分别代表空气质量、肺功能、吸烟习惯、咳嗽症状。你想学习它们之间的贝叶斯网络结构。 (1) 简述使用搜索+评分方法（如K2算法）学习网络结构的步骤。 (2) 若你有一个先验知识：吸烟会影响肺功能和咳嗽，空气质量也会影响肺功能和咳嗽。如何将此先验嵌入结构学习？ (3) 为什么学习得到的网络不一定代表因果结构？举例说明。</p><h2 id="模型选择与过拟合" tabindex="-1">模型选择与过拟合：</h2><p>你使用EM算法拟合一个含5个隐类的高斯混合模型，训练数据似然值很高，但在测试集上性能差。 (1) 这种现象叫什么？可能原因是什么？ (2) 提出两种方法选择合适数量的隐类（即模型选择）。 (3) 如果使用BIC评分，假设训练样本数N=500，模型参数个数d=30，BIC = -2 ln L + d ln N。若训练似然 ln L = -1000，计算BIC。若有更简单模型（d=15，ln L=-1020），哪个更好？</p><h2 id="医疗诊断中的隐变量模型" tabindex="-1">医疗诊断中的隐变量模型：</h2><p>你想构建一个疾病诊断系统，症状可观测（发烧、咳嗽、疲劳），但潜在的疾病种类（感冒、流感、新冠）未标注。 (1) 解释为什么这是一个隐变量模型。 (2) 使用EM算法学习模型参数时，需要哪些概率分布假设？ (3) 如果部分病人的疾病已被医生标注，你如何利用这些标注数据改进学习？（提示：半监督学习） (4) 评价该模型的可解释性与预测性能之间的权衡。</p>',20)])])}const s=t(o,[["render",d]]);export{c as __pageData,s as default};
